{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have a public access block configured, which could lead to accidental data exposure if bucket policies or ACLs are misconfigured."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "Server-side encryption is not explicitly enabled. While AWS provides default encryption (SSE-S3), best practice for sensitive backend state files is to use SSE-KMS for better control and auditability."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "Versioning is not enabled on the bucket. For Terraform state backends, versioning is critical to prevent data loss from accidental overwrites or deletions of state files."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "LOW",
      "explanation": "Access logging is not enabled. Enabling it helps track requests made against the bucket, which is useful for security auditing and troubleshooting."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "changeme_aws_s3_bucket_backend_simple" {
  force_destroy = true
  bucket        = "changeme-${random_id.changeme_backends_s3_bucket_name.hex}"
}

resource "aws_s3_bucket_public_access_block" "changeme_aws_s3_bucket_backend_simple" {
  bucket                  = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "changeme_aws_s3_bucket_backend_simple" {
  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "changeme_aws_s3_bucket_backend_simple" {
  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "changeme_aws_s3_bucket_backend_simple" {
  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id

  target_bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id # In production, this should be a separate log bucket
  target_prefix = "log/"
}",
  "fix_summary": "Added `aws_s3_bucket_public_access_block` to prevent public access. Added `aws_s3_bucket_server_side_encryption_configuration` to enforce SSE-KMS encryption. Added `aws_s3_bucket_versioning` to enable versioning for state file protection. Added `aws_s3_bucket_logging` to enable access logging (note: in a real production environment, logs should typically go to a separate dedicated bucket)."
}
